    return datetime(2025, 6, 1, 12, 0, 0, tzinfo=timezone.utc)


class TestNextId:
    def test_starts_at_one(self, repo):
        assert repo.next_id() == 1

    def test_increments(self, repo):
        repo.next_id()
        assert repo.next_id() == 2


class TestAdd:
    def test_add_and_get(self, repo, now):
        task = Task(id=1, title="Test", created_at=now)
        repo.add(task)
        assert repo.get(1) == task

    def test_add_duplicate_raises(self, repo, now):
        task = Task(id=1, title="Test", created_at=now)
        repo.add(task)
        with pytest.raises(ValueError, match="already exists"):
            repo.add(task)


class TestGet:
    def test_get_missing_returns_none(self, repo):
        assert repo.get(999) is None


class TestList:
    def test_list_empty(self, repo):
        assert list(repo.list()) == []

    def test_list_returns_all(self, repo, now):
        t1 = Task(id=1, title="A", created_at=now)
        t2 = Task(id=2, title="B", created_at=now)
        repo.add(t1)
        repo.add(t2)
        result = list(repo.list())
        assert len(result) == 2


class TestUpdate:
    def test_update_existing(self, repo, now):
        task = Task(id=1, title="Original", created_at=now)
        repo.add(task)
        task.title = "Updated"
        repo.update(task)
        assert repo.get(1).title == "Updated"

    def test_update_missing_raises(self, repo, now):
        task = Task(id=99, title="Ghost", created_at=now)
        with pytest.raises(KeyError):
            repo.update(task)


class TestDelete:
    def test_delete_existing(self, repo, now):
        task = Task(id=1, title="Del", created_at=now)
        repo.add(task)
        assert repo.delete(1) is True
        assert repo.get(1) is None

    def test_delete_missing(self, repo):
        assert repo.delete(999) is False


class TestNormalizeTags:
    def test_dedup_and_normalize(self):
        result = normalize_tags(["Work", "  WORK  ", "home"])
        names = [t.name for t in result]
        assert names == ["work", "home"]

    def test_accepts_tag_objects(self):
        result = normalize_tags([Tag("alpha"), Tag("Alpha")])
        assert len(result) == 1
        assert result[0].name == "alpha"

    def test_empty_input(self):
        assert normalize_tags([]) == []

    def test_invalid_tag_raises(self):
        with pytest.raises(ValueError):
            normalize_tags([""])
